174	<body>
175	  <main>
176	    <h1 class="visually-hidden">Animated Circle</h1>
177	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
178	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
179	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
180	      </svg>
181	    </button>
182	    <p class="status" id="status" role="status">Blue</p>
183	    <p class="hint" id="hint"><span class="verb">Click</span> to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>; hold <kbd>Shift</kbd> to go back)</p>
184	  </main>
185	  <script>
186	    const button = document.querySelector('button');
187	    const status = document.querySelector('.status');
188	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
189	    const storageKey = 'circle-color';
190	
191	    function loadColor() {
192	      try {
193	        return localStorage.getItem(storageKey);
194	      } catch {
195	        return null;
196	      }
197	    }
198	
199	    function saveColor(color) {
200	      try {
201	        localStorage.setItem(storageKey, color);
202	      } catch {}
203	    }
204	
205	    const savedColor = loadColor();
206	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
207	
208	    function applyColor() {
209	      const color = colors[index];
210	      if (color === 'blue') {
211	        delete button.dataset.color;
212	      } else {
213	        button.dataset.color = color;
214	      }
215	      status.textContent = color[0].toUpperCase() + color.slice(1);
216	    }
217	
218	    function changeColor(event) {
219	      const step = event.shiftKey ? -1 : 1;
220	      index = (index + step + colors.length) % colors.length;
221	      applyColor();
222	      saveColor(colors[index]);
223	
224	      button.classList.remove('color-changed');
225	      void button.offsetWidth;
226	      button.classList.add('color-changed');
227	    }
228	
229	    applyColor();
230	    requestAnimationFrame(() => {
231	      requestAnimationFrame(() => button.classList.remove('no-transition'));
232	    });
233	
234	    if (matchMedia('(hover: none)').matches) {
235	      document.querySelector('.hint .verb').textContent = 'Tap';
236	    }
237	
238	    button.addEventListener('click', changeColor);
239	    button.addEventListener('animationend', () => {
240	      button.classList.remove('color-changed');
241	    });
242	    addEventListener('storage', (event) => {
243	      if (event.key === storageKey && colors.includes(event.newValue)) {
244	        index = colors.indexOf(event.newValue);
245	        applyColor();
246	      }
247	    });
248	  </script>
249	</body>
250	</html>
