p='0.html';s=open(p).read()
s=s.replace("""    function changeColor(event) {
      const step = event.shiftKey ? -1 : 1;
      index""","""    function changeColor(step) {
      index""")
s=s.replace("""    button.addEventListener('click', changeColor);""","""    // Keyboard-synthesized clicks don't reliably carry shiftKey across
    // browsers, so read modifiers from keydown directly.
    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
    button.addEventListener('keydown', (event) => {
      if (event.altKey || event.ctrlKey || event.metaKey) return;
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        if (!event.repeat || event.key === 'Enter') changeColor(event.shiftKey ? -1 : 1);
      } else if (event.key in keySteps) {
        event.preventDefault();
        changeColor(keySteps[event.key]);
      }
    });
    button.addEventListener('click', (event) => {
      // detail === 0 means keyboard/AT activation; keydown already handled keys,
      // but assistive tech may fire click without keydown.
      if (event.detail === 0 && keyHandled) return;
      changeColor(event.shiftKey ? -1 : 1);
    });""")
open(p,'w').write(s)
EOF

